138	/// Auto-vectorized norm reduction kernel, modeled after the `arrayDotProduct` kernel. Manual unrolling
139	/// with independent accumulators breaks the FP dependency chain so the compiler can keep several SIMD
140	/// registers in flight and (for `L2`/`L2Squared`) fuse `a*b + c` into FMA.
141	///
142	/// The whole row loop lives inside this single multitarget call: an `x86_64_v4` (AVX-512) specialisation
143	/// cannot be inlined into the `v2`-baseline caller, so a per-row call would impose a hard boundary every
144	/// ~150 elements that interrupts the hardware prefetcher's stream. Batching all rows into one call keeps
145	/// the load stream continuous across row boundaries, which matters for the bandwidth-bound `Float64` paths.
146	MULTITARGET_FUNCTION_X86_V4(
147	    MULTITARGET_FUNCTION_HEADER(template <typename Kernel, typename ResultType, typename ArgumentType> static void NO_SANITIZE_UNDEFINED NO_INLINE),
148	    normBatchImpl,
149	    MULTITARGET_FUNCTION_BODY((
150	        const ArgumentType * __restrict data,
151	        const ColumnArray::Offset * __restrict offsets,
152	        ResultType * __restrict result_data,
153	        size_t input_rows_count,
154	        const typename Kernel::ConstParams & params)
155	    {
156	        constexpr size_t unroll_count = 16;
157	        ColumnArray::Offset prev = 0;
158	        for (size_t row = 0; row < input_rows_count; ++row)
159	        {
160	            const size_t count = offsets[row] - prev;
161	            const ArgumentType * __restrict row_data = data + prev;
162	
163	            ResultType partial_results[unroll_count]{};
164	            size_t i = 0;
165	            const size_t unrolled_end = count / unroll_count * unroll_count;
166	            for (; i < unrolled_end; i += unroll_count)
167	                for (size_t s = 0; s < unroll_count; ++s)
168	                    partial_results[s] = Kernel::template accumulate<ResultType>(partial_results[s], static_cast<ResultType>(row_data[i + s]), params);
169	
170	            ResultType result = 0;
171	            for (auto & partial_result : partial_results)
172	                result = Kernel::template combine<ResultType>(result, partial_result, params);
173	
174	            for (; i < count; ++i)
175	                result = Kernel::template accumulate<ResultType>(result, static_cast<ResultType>(row_data[i]), params);
176	
177	            result_data[row] = Kernel::finalize(result, params);
178	            prev = offsets[row];
179	        }
180	    }))
